```js
export function parseDuration(text) {
  const source = String(text ?? '').trim()
  if (!source.startsWith('P')) return null

  const body = source.slice(1)
  const tIndex = body.indexOf('T')
  const inTime = tIndex !== -1
  const datePart = inTime ? body.slice(0, tIndex) : body
  const timePart = inTime ? body.slice(tIndex + 1) : null
  if (timePart === '') return null // "P1DT" — a T with nothing after it

  const dateSeconds = scan(datePart, DATE_UNIT_SECONDS, DATE_ORDER, inTime)
  if (dateSeconds === null) return null
  const timeSeconds = inTime ? scan(timePart, TIME_UNIT_SECONDS, TIME_ORDER, false) : 0
  if (timeSeconds === null) return null

  return Math.round((dateSeconds + timeSeconds) * 1000)
}
```

